// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2015, "8-9", [{"author":"Л. Фёдорова","question":"В каком слове -<em>метр</em> означает не то же, что в остальных?","choices":["<em>амперметр</em>","<em>вольтметр</em>","<em>километр</em>","<em>спидометр</em>","<em>термометр</em>."],"key":"В","review":["Два смысла части «-метр»","Уточни, обозначает ли слово прибор для измерения или единицу измерения.","Амперметр, вольтметр, спидометр и термометр — приборы. Километр — единица длины, равная тысяче метров."]},{"author":"Е. Бикмаев","question":"Иногда, если допустить в слове ошибку, можно получить другое слово. Какое из данных ниже слов существует в русском языке?","choices":["<em>парашут</em>","<em>жури</em>","<em>шют</em>","<em>жють</em>","<em>брошура</em>."],"key":"Б","review":["Слово вместо опечатки","Угадай, какие слова намеревались написать. Потом отдельно проверь, можно ли употребить написанную форму с другим значением.","«Жури» — повелительная форма глагола «журить», то есть слегка порицать. Заимствованное название судейской группы пишется «жюри»."]},{"author":"А. Сомин","question":"Даны арабские глаголы (записанные в латинской транскрипции) и их переводы на русский язык: saara ‘двигаться’, dabba ‘ползать’, qatara ‘идти гуськом’. Переведите с арабского языка слова sayara, dabaaba и qitaar.","choices":["<em>поезд</em>, <em>танк</em>, <em>автомобиль</em>","<em>поезд</em>, <em>вездеход</em>, <em>автобус</em>","<em>автомобиль</em>, <em>танк</em>, <em>поезд</em>","<em>автомобиль</em>, <em>трамвай</em>, <em>автобус</em>","<em>танк</em>, <em>трамвай</em>, <em>поезд</em>."],"key":"В","review":["Арабские названия транспорта","Сопоставь слова, в которых повторяются согласные. Для «идти гуськом» ищи транспорт, состоящий из частей, идущих одна за другой.","«Qitaar» связан с «qatara» и значит «поезд». «Dabaaba» связано с «ползать» и обозначает танк. «Sayara» — автомобиль."]},{"author":"Е. Муравенко","question":"В какой паре слов соотношение между смыслами слов не такое, как в остальных парах?","choices":["<em>политика — политик</em>","<em>физика — физик</em>","<em>логика — логик</em>","<em>математика — математик</em>","<em>динамика — динамик</em>."],"key":"Д","review":["Названия и люди","Проверь, называет ли первое слово область знаний или деятельности, а второе — человека, который ею занимается.","Политик, физик, логик и математик занимаются соответствующей деятельностью. Динамик — устройство, которое воспроизводит звук."]},{"author":"А. Пиперски и А. Сомин","question":"В каком из этих слов предпоследнюю букву можно проверить однокоренными словами?","choices":["<em>полиция</em>","<em>милиция</em>","<em>линия</em>","<em>компания</em>","<em>серия</em>."],"key":"Д","review":["Проверочное слово","Посмотри, в каком семействе слов предпоследнюю гласную можно поставить под ударение.","В «се́рия» сомнение вызывает «и». В однокоренном «сери́йный» гласная ударная, её написание можно проверить."]},{"author":"Е. Ренковская","question":"Какое из существительных не обозначает процесс?","choices":["<em>листопад</em>","<em>снегопад</em>","<em>звездопад</em>","<em>водопад</em>","<em>камнепад</em>."],"key":"Г","review":["Событие или место","Проверь, описывает ли слово то, что происходит, или называет объект, где что-то происходит.","Листопад, снегопад, звездопад и камнепад описывают падение листьев, снега, звёзд и камней. Водопад — водный поток и место, где он падает с уступа."]},{"author":"И. Рубанов и Л. Фёдорова","question":"Что может быть острым, но не может быть тупым?","choices":["угол","боль","игла","блюдо","упрямство."],"key":"Г","review":["У чего бывает острота","Сравни слово «острый» в прямом и переносном значениях. Для каждого из них подбери обычное противопоставление.","Угол, боль, игла и упрямство могут сочетаться со словом «тупой». Острым блюдом называют приправленное, а противопоставляют ему пресное блюдо."]},{"author":"К. Гилярова и Б. Иомдин","question":"Даны существительные: <em>оркестр, автобус, наставник, трепет</em>. Какое прилагательное не сочетается ни с одним из них?","choices":["<em>духовный</em>","<em>духовой</em>","<em>душевный</em>","<em>душевой</em>","<em>душный</em>."],"key":"Г","review":["Прилагательные и сочетания","Попробуй распределить существительные по прилагательным, начиная с хорошо знакомых сочетаний.","Есть «духовой оркестр», «духовный наставник», «душевный трепет» и «душный автобус». «Душевой» обычно относится к душу, например «душевая кабина»."]},{"author":"П. Аркадьев","question":"Какое из данных в ответах слов заметно отличается по смыслу от остальных?","choices":["<em>бас</em>","<em>контрабас</em>","<em>контральто</em>","<em>сопрано</em>","<em>тенор</em>."],"key":"Б","review":["Певческие голоса и инструмент","Различи названия человеческих голосов и музыкального инструмента. Совпадение частей слов может мешать.","Бас, контральто, сопрано и тенор — названия голосов. Контрабас — струнный музыкальный инструмент."]},{"author":"Е. Муравенко","question":"В какой паре глаголы совершенного и несовершенного вида соотносятся по смыслу не так, как в других?","choices":["<em>забе́гать ― забега́ть</em>","<em>насы́пать ― насыпа́ть</em>","<em>отре́зать ― отреза́ть</em>","<em>прода́ть ― продава́ть</em>","<em>разру́шить ― разруша́ть</em>."],"key":"А","review":["Вид и значение глагола","Сравни не только вид, но и само действие. Для первой пары придумай примеры с разными ударениями.","«Забе́гать» значит начать бегать. «Забега́ть» значит, например, ненадолго заходить или вбегать. В остальных парах меняется вид, а основное действие остаётся тем же."]},{"author":"С. Бурлак","question":"Какое из данных слов можно понять и как прилагательное, и как причастие?","choices":["<em>прост</em>","<em>сложен</em>","<em>лёгок</em>","<em>труден</em>","<em>прекрасен</em>."],"key":"Б","review":["Прилагательное или причастие","Прочитай слово в двух фразах: «пример ___» и «чемодан ___ перед поездкой».","«Пример сложен» значит «пример труден». «Чемодан сложен» описывает результат действия «сложить». У «сложен» есть и краткое прилагательное, и краткое причастие."]},{"author":"Б. Иомдин","question":"Какое слово чаще встречается после частицы <em>ни</em>, чем после других слов?","choices":["<em>берись</em>","<em>возьмись</em>","<em>держись</em>","<em>крепись</em>","<em>сердись</em>."],"key":"Б","review":["Частица перед глаголом","Вспомни оборот о том, что что-то неожиданно появилось неизвестно откуда.","В обороте «откуда ни возьмись» частица «ни» непосредственно предшествует «возьмись». Этим частым употреблением оно выделяется среди других форм."]},{"author":"Б. Иомдин","question":"В каком из примеров подчёркнутое слово называет женщину по иному принципу, чем в остальных?","choices":["<em>Вообще-то я не верю в этих молодых следовательниц, двадцатипятилетних <u>прокурорш</u> и оперативниц</em>. (Ю. Домбровский)","<em><u>Профессорша</u> пекла на дорогу Дмитрию коржики, профессор в кабинете готовился к лекции</em>. (В. Вересаев)","<em>— Может, помочь принести? — предложил Элек. — Не моя смена, ― отозвалась <u>почтальонша</u>. ― Корреспонденцию доставляют утром</em>. (Е. Велтистов)","<em><u>Докторша</u> улыбнулась так, как будто она не уколы делала, а раздавала конфеты</em>. (Ф. Искандер)","<em>Сидел вполоборота к столу пожилой <u>библиотекарши</u> Надежды Никифоровны, пока та где-то за шкафами искала ему книги</em>. (Е. Водолазкин)"],"key":"Б","review":["Основание для названия","Проверь по контексту, занимается ли названная женщина этой работой сама или названа по профессии другого человека.","В цитате Вересаева профессорша печёт коржики, пока профессор готовится к лекции. Здесь «профессорша» — жена профессора. Другие слова называют женщин по их собственной работе."]},{"author":"И. Шаронов","question":"С какими падежами может сочетаться предлог <em>по</em>?","choices":["с дательным, винительным и предложным","с дательным, творительным и предложным","только с дательным и предложным","только с дательным и винительным","только с дательным."],"key":"А","review":["Падежи после «по»","Составь сочетания о пути, границе и завершении действия. У одного предлога в них могут быть разные падежи.","«По дороге» — дательный, «по колено» — винительный, «по окончании» — предложный. Возможны все три падежа."]},{"author":"С. Сай","question":"От какого глагола не может синтаксически зависеть инфинитив (неопределённая форма глагола)?","choices":["<em>выпасть</em>","<em>получаться</em>","<em>довестись</em>","<em>произойти</em>","<em>случаться</em>."],"key":"Г","review":["Инфинитив при глаголе","Подставь «встретить» после форм «выпало», «получалось», «довелось», «произошло» и «случалось».","Можно «выпало встретить», «получалось встретить», «довелось встретить», «случалось встретить». После «произошло» ожидается название события, и сочетание «произошло встретить» не получается."]},{"author":"М. Рубинштейн","question":"Маша искала в интернете примеры употребления некоторого слова и заметила, что чаще всего оно сочетается со словами <em>следует</em>, <em>необходимо</em>, <em>хочу</em> и подобными. Какое слово Маша искала?","choices":["<em>оступиться</em>","<em>ослышаться</em>","<em>оговориться</em>","<em>обсчитаться</em>","<em>опечататься</em>."],"key":"В","review":["Глагол после «необходимо»","Ищи действие, которое говорящий может захотеть сделать намеренно. Человек иногда прерывает речь, чтобы добавить оговорку.","«Хочу оговориться» может значить «хочу сделать оговорку». У других глаголов приведённые действия обычно случайны, поэтому их реже намереваются совершить."]},{"author":"Л. Фёдорова","question":"В какой паре слова даны не в том порядке, что в остальных?","choices":["<em>безликий — безличный</em>","<em>непроходимый — непереходный</em>","<em>пунктуальный — пунктуационный</em>","<em>обвинительный — винительный</em>","<em>страдательный — сострадательный</em>."],"key":"Д","review":["Грамматическое название","Найди в каждой паре прилагательное, которое употребляется как термин. Сравни его место в списке.","«Безличный», «непереходный», «пунктуационный» и «винительный» стоят вторыми. «Страдательный», как в сочетании «страдательный залог», стоит первым."]},{"author":"Е. Бикмаев","question":"Заполните пробел в отрывке из шуточного стихотворения Козьмы Пруткова «Доблестные студиозусы»:\n<em>Здорово, наш старый товарищ!\nРеши поскорее наш спор:\nКто доблестней, Кох или Вагнер?» —\nСпросили с бряцанием шпор.\nЯ комнату взглядом окинул\nИ, будто узором прельщён:\n«Мне нравятся очень... _____!» —\nСказал им и выбежал вон.</em>","choices":["<em>картины</em>","<em>гардины</em>","<em>рисунки</em>","<em>портьеры</em>","<em>обои</em>."],"key":"Д","review":["Отступление от спора","Герой уклоняется от ответа на вопрос о доблести и вместо этого называет то, чей узор видит в комнате.","В тексте Пруткова герой говорит, что ему нравятся обои. Они и могли привлечь его внимание узором."]},{"author":"С. Сай","question":"В автобиографическом произведении «Вольный проезд» Марина Цветаева говорит об одном из следующих слов, что в нём произошло «глупое упразднение» одной согласной буквы. Хотя этимологические словари и не подтверждают мнения Цветаевой, попробуйте понять, какое слово она имела в виду.","choices":["<em>белокурый</em>","<em>курильщик</em>","<em>курица</em>","<em>куролесить</em>","<em>курорт</em>."],"key":"А","review":["Слово у Цветаевой","Поищи среди ответов слово, где одна буква могла бы связать часть слова с «кудрями».","Цветаева предлагала видеть в «белокурый» форму «белокудрый» с пропущенным «д». Именно «белокурый» она обсуждает в «Вольном проезде»."]},{"author":"И. Иткин","question":"У знаменитого русского поэта Гаврилы Романовича Державина есть строка, которую иногда неправильно воспроизводят в таком виде: <em>Я иду с мечом, судия</em>. Какую замену нужно сделать, чтобы строка стала правильной?","choices":["<em>иду</em> на <em>йду</em>","<em>иду</em> на <em>еду</em>","<em>с</em> на <em>з</em>","<em>мечом</em> на <em>мечем</em>","<em>судия на судья</em>."],"key":"Г","review":["Строка, читаемая с конца","Убери пробелы и проверь, одинаково ли читается фраза слева направо и справа налево.","После замены «мечом» на «мечем» получается «яидусмечемсудия». Это палиндром, который читается одинаково в обоих направлениях."]},{"author":"Б. Иомдин","question":"Что делали самые первые мошенники?","choices":["воровали кошельки","угоняли коней","разбойничали на дорогах","обыгрывали в карты","подделывали документы."],"key":"А","review":["Откуда взялось «мошенник»","Вспомни старое слово «мошна». Оно обозначало вещь, в которой носили деньги.","Мошна — кошель. Мошенниками первоначально называли тех, кто крал мошны, то есть чужие кошельки."]},{"author":"Л. Фёдорова","question":"<em>С жару</em>, <em>к жару</em>, <em>в жару.</em> Сколько разных падежей можно здесь обнаружить?","choices":["один","два","три","четыре","пять."],"key":"Г","review":["Падежи у формы «жару»","Проверь, от какого существительного образована форма в каждом обороте. «Жару» бывает формой и от «жар», и от «жара».","«С жару» — родительный, «к жару» — дательный. «В жару» может быть предложной формой «жар» или винительной формой «жара». Всего четыре падежа."]},{"author":"А. Пиперски","question":"На одном сайте в интернете цитируется строка из «Большой элегии Джону Донну» Иосифа Бродского: <em>Спят клёны, сосны, крабы, пихты, ель</em>. Здесь допущена одна опечатка. Какая буква оригинала была заменена на неправильную?","choices":["<em>а</em>","<em>б</em>","<em>в</em>","<em>г</em>","<em>д.</em>"],"key":"Г","review":["Опечатка среди деревьев","Ряд состоит из названий деревьев. Найди слово, которое выпало из этой группы.","У Бродского в строке стоят «грабы», ещё один вид деревьев. В опечатке первая буква «г» заменилась на «к»."]},{"author":"Е. Добрушина","question":"Какое из этих существительных имеет необычное происхождение: образовалось с участием формы родительного падежа и хранит в своей основе часть бывшего окончания?","choices":["<em>пролог</em>","<em>итог</em>","<em>демагог</em>","<em>порог</em>","<em>слог</em>."],"key":"Б","review":["След падежного окончания","Вспомни, как перед окончательной суммой говорят «и того столько-то». Проверь, можно ли получить существительное из этой формулы.","«Итог» связано с сочетанием «и того». Согласная «г» из бывшего окончания родительной формы «того» вошла в основу существительного."]},{"author":"Л. Фёдорова","question":"Что придумал живший в XVII веке француз Франсуа Мансар?","choices":["рецепт фамильного сыра","балюстрады","жильё под самой крышей","садовую беседку-павильон","балкон."],"key":"В","review":["Фамилия архитектора","Попробуй назвать каждое сооружение одним словом. Одно из этих названий связано с фамилией Мансар.","Жилое помещение под крышей называется мансардой. Его название происходит от фамилии французского архитектора Мансара."]},{"author":"А. Пиперски","question":"Полабский язык — один из славянских языков, на котором говорили до XVIII века на северо-западе современной Германии. Заполните пропуск в арифметическом выражении на полабском языке: citĕr × … = disątnocti.","choices":["visĕmnocti","tåri","citĕr","pąt","sisdiśǫt."],"key":"Г","review":["Полабское умножение","Сопоставь «citĕr» с числом «четыре». В полабском «disątnocti» означает «двадцать».","Четыре надо умножить на пять. Полабское «pąt» — «пять», соответствующая славянская форма."]},{"author":"А. Пиперски","question":"Русскоязычный Викисловарь содержит словарные статьи, посвящённые словам разных языков (в том числе очень редким). Какая из этих пяти случайным образом выбранных статей описывает слово не русского, а украинского языка?","choices":["<em>вампука</em>","<em>кристалограф</em>","<em>наморивший</em>","<em>оттяпывать</em>","<em>схорон</em>."],"key":"Б","review":["Словарная статья","Сравни, в какой форме приведены редкие слова. В одном из них заметно отличие от русского написания соответствующего термина.","Украинское «кристалограф» пишется с одним «л». По-русски — «кристаллограф», с удвоением «л»."]},{"author":"С. Сай","question":"Студент-филолог классифицировал некоторые слова и словосочетания русского языка. Приведены примеры выражений, попавших в разные группы:\n1) <em>декабрь, семнадцатый век</em>; 2) <em>вторник, полдень</em>;\n3) <em>прошлое лето, глубокая ночь</em>; 4) <em>следующая неделя, рассвет</em>.\nВ какую группу должно было попасть выражение <em>второе число</em>?","choices":["в первую","во вторую","в третью","в четвёртую","ни в одну из перечисленных."],"key":"Д","review":["Выражения о времени","Ответь с каждым выражением на вопрос «когда?». Смотри на падеж и на предлог, которые нужны в ответе.","Есть «в декабре», «во вторник», «прошлым летом», «на следующей неделе». Для «второго числа» нужен родительный без предлога. Такой схемы среди четырёх групп нет."]},{"author":"Е. Муравенко","question":"Маленький Даня недавно начал говорить и в некоторых словах меняет местами согласные звуки, с которых начинаются второй и третий слоги, например, вместо <em>молоко</em> говорит <em>моколо</em>. Какое из слов в Данином произношении будет звучать так же, как правильно произнесённое другое слово русского языка?","choices":["<em>полететь</em>","<em>полежать</em>","<em>покатать</em>","<em>подарок</em>","<em>перелить</em>."],"key":"В","review":["Переставленные согласные","Разбей слова на слоги и в каждом поменяй местами начальные согласные второго и третьего слогов.","При перестановке «по-ка-тать» превращается в «по-та-кать». «Потакать» — самостоятельное слово со значением «потворствовать»."]},{"author":"А. Пиперски","question":"В одной из так называемых стихограмм Дмитрия Александровича Пригова встречаются такие строки: <em>Парк культуры</em>, <em>Скверкультуры</em>, <em>Тропикильтуры</em>, <em>Проливультуры</em>. А какая ещё строка есть в этой стихограмме?","choices":["<em>Полуостровуры</em>","<em>Моретуры</em>","<em>Заливультуры</em>","<em>Полекультуры</em>","<em>Перешеекуры</em>."],"key":"А","review":["Строка стихограммы","Сосчитай знаки в первых строках, включая пробел в «Парк культуры». Следи за тем, как географические названия соединяются с окончанием «культуры».","Все приведённые строки занимают по 13 знаков. Такую же длину имеет «Полуостровуры», где к «полуостров» присоединён хвост «уры»."]}], {"year":2015,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2015-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
